from langchain_core.messages import (
    HumanMessage, 
    AIMessage, 
    SystemMessage, 
    ToolMessage,
    FunctionMessage
)

# 1. SystemMessage: Sets the behavior/persona
system_msg = SystemMessage(content="You are a senior Java performance engineer.")

# 2. HumanMessage: The user's input
human_msg = HumanMessage(content="Explain the impact of object allocation in a high-throughput loop.")

# 3. AIMessage: The response generated by the model
ai_msg = AIMessage(content="Excessive allocation leads to frequent GC pauses, increasing tail latency...")

# 4. ToolMessage: Represents the output from a tool call (e.g., a search or calculation)
# Requires 'tool_call_id' to associate it with the specific tool request
tool_msg = ToolMessage(
    content="GC throughput metrics: 98.5% efficiency", 
    tool_call_id="call_12345"
)

# 5. FunctionMessage: Used for legacy function-calling (now mostly replaced by ToolMessage)
func_msg = FunctionMessage(
    name="get_memory_metrics", 
    content="Heap usage at 450MB"
)

# Example: Putting them in a list for a model's chat history
messages = [system_msg, human_msg, ai_msg, tool_msg, func_msg]

for msg in messages:
    print(msg.content)

